// ── PRIMITIVES ────────────────────────────────────────────
const Tag=({c="beige",children})=>{const m={gold:{color:T.gold,border:"rgba(138,106,56,.35)",bg:T.goldL},green:{color:T.green,border:"rgba(74,122,66,.3)",bg:T.greenL},red:{color:T.red,border:"rgba(139,58,58,.3)",bg:T.redL},blue:{color:T.blue,border:"rgba(58,90,139,.3)",bg:T.blueL},beige:{color:T.brown2,border:"rgba(184,149,95,.4)",bg:"rgba(184,149,95,.1)"},silver:{color:T.brown3,border:T.lineL,bg:"transparent"},orange:{color:T.orange,border:"rgba(139,106,58,.35)",bg:"rgba(139,106,58,.08)"},vip:{color:"#C8952A",border:"rgba(200,149,42,.4)",bg:"rgba(200,149,42,.08)"}};const s=m[c]||m.beige;return <span style={{display:"inline-block",fontSize:".46rem",letterSpacing:".18em",textTransform:"uppercase",padding:".28rem .75rem",border:`1px solid ${s.border}`,color:s.color,background:s.bg}}>{children}</span>;};

const Btn=({v="primary",sz="md",full,onClick,children,style={}})=>{const[h,setH]=useState(false);const sz2={sm:{padding:".5rem 1.1rem",fontSize:".5rem"},md:{padding:".8rem 1.8rem",fontSize:".54rem"},lg:{padding:"1rem 2.5rem",fontSize:".56rem"}};const vs={primary:{bg:T.brown,color:T.cream,border:T.brown},outline:{bg:"transparent",color:T.brown,border:T.brown},gold:{bg:T.gold,color:T.ivory,border:T.gold},ghost:{bg:"transparent",color:T.brown3,border:"transparent"}};const vt=vs[v]||vs.primary;const hv=h?(v==="primary"?{background:T.brown2}:v==="outline"?{background:T.brown,color:T.cream}:{}):{};return <button onClick={onClick} onMouseEnter={()=>setH(true)} onMouseLeave={()=>setH(false)} style={{display:"inline-flex",alignItems:"center",justifyContent:"center",gap:".5rem",fontFamily:"'Montserrat',sans-serif",fontWeight:500,letterSpacing:".18em",textTransform:"uppercase",background:vt.bg,color:vt.color,border:`1px solid ${vt.border}`,cursor:"pointer",transition:"all .3s",borderRadius:0,whiteSpace:"nowrap",...(sz2[sz]||sz2.md),...(full?{width:"100%"}:{}),...hv,...style}}>{children}</button>;};

const Card=({title,actions,children,style={}})=>(<div style={{background:T.ivory,marginBottom:"1rem",...style}}>{title&&<div style={{padding:"1rem 1.5rem",display:"flex",justifyContent:"space-between",alignItems:"center",borderBottom:`1px solid ${T.lineL}`,flexWrap:"wrap",gap:".5rem"}}><span style={{fontSize:".56rem",letterSpacing:".2em",textTransform:"uppercase",color:T.brown,fontWeight:500}}>{title}</span>{actions&&<div style={{display:"flex",gap:".5rem",flexWrap:"wrap"}}>{actions}</div>}</div>}{children}</div>);

const KPI=({label,value,sub,subColor,icon:Icon})=>(<div style={{background:T.ivory,padding:"1.4rem 1.5rem"}}><div style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",marginBottom:".6rem"}}><div style={{fontSize:".46rem",letterSpacing:".2em",textTransform:"uppercase",color:T.brown3,fontWeight:500}}>{label}</div>{Icon&&<span style={{color:T.gold}}><Icon/></span>}</div><div style={{fontFamily:"'Cormorant Garamond',serif",fontSize:"1.9rem",fontWeight:400,lineHeight:1,color:T.brown,marginBottom:".3rem"}}>{value}</div>{sub&&<div style={{fontSize:".54rem",color:subColor||T.brown3}}>{sub}</div>}</div>);

const Alert=({type="gold",icon,children})=>{const colors={gold:{bg:T.goldL,border:"rgba(138,106,56,.25)",color:T.gold},red:{bg:T.redL,border:"rgba(139,58,58,.25)",color:T.red},green:{bg:T.greenL,border:"rgba(74,122,66,.25)",color:T.green},blue:{bg:T.blueL,border:"rgba(58,90,139,.25)",color:T.blue}};const c=colors[type]||colors.gold;const Icon=icon;return <div style={{background:c.bg,border:`1px solid ${c.border}`,padding:".9rem 1.2rem",marginBottom:".8rem",display:"flex",alignItems:"flex-start",gap:".75rem"}}>{Icon&&<span style={{color:c.color,flexShrink:0,marginTop:1}}><Icon/></span>}<div style={{fontSize:".6rem",lineHeight:1.85,color:T.brown2}}>{children}</div></div>;};

const Divider=()=>(<div style={{display:"flex",alignItems:"center",gap:"1.5rem",margin:"1.5rem 0"}}><div style={{flex:1,height:"0.5px",background:T.line}}/><span style={{fontFamily:"'Cormorant Garamond',serif",fontSize:".9rem",color:T.gold}}>✦</span><div style={{flex:1,height:"0.5px",background:T.line}}/></div>);

const Logo=()=>(<div><div style={{fontFamily:"'Cormorant Garamond',serif",fontSize:"1rem",letterSpacing:".2em",color:T.brown,whiteSpace:"nowrap",fontWeight:400}}>K PROPERTIES</div><div style={{display:"flex",alignItems:"center",gap:".5rem",marginTop:".25rem"}}><div style={{flex:1,height:"0.5px",background:T.gold}}/><div style={{fontSize:".3rem",letterSpacing:".3em",textTransform:"uppercase",color:T.gold,whiteSpace:"nowrap"}}>AFRIGROUPE · ABIDJAN</div><div style={{flex:1,height:"0.5px",background:T.gold}}/></div></div>);

const BarChart=()=>(<div style={{display:"flex",alignItems:"flex-end",gap:4,height:120}}>{["J","F","M","A","M","J","J","A","S","O","N","D"].map((l,i)=>(<div key={l} style={{display:"flex",flexDirection:"column",alignItems:"center",gap:3,flex:1}}><div style={{width:"100%",height:`${[25,40,35,55,50,65,75,60,70,80,85,68][i]}%`,background:`linear-gradient(to top,${T.gold},${T.goldL})`,borderTop:`1px solid ${T.gold}`}}/><div style={{fontSize:".4rem",color:T.brown3}}>{l}</div></div>))}</div>);

const TL=({items})=>(<div style={{padding:"1.2rem 1.5rem"}}>{items.map(([st,t,s,d],i)=>(<div key={i} style={{display:"flex",gap:"1rem",padding:".7rem 0",position:"relative"}}>{i<items.length-1&&<div style={{position:"absolute",left:9,top:22,width:1,height:"100%",background:T.lineL}}/>}<div style={{width:20,height:20,border:`1px solid ${st==="done"?T.gold:st==="active"?T.gold:T.line}`,background:st==="done"?T.gold:st==="active"?T.goldL:"transparent",display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,marginTop:2,color:st==="done"?T.ivory:T.gold}}>{st==="done"&&<I.Check/>}{st==="active"&&<span style={{fontSize:".5rem",fontWeight:600}}>→</span>}</div><div style={{flex:1}}><div style={{fontSize:".62rem",fontWeight:500,color:st==="active"?T.gold:st==="pending"?T.brown3:T.brown,marginBottom:".2rem"}}>{t}</div><div style={{fontSize:".55rem",color:T.brown3}}>{s}</div></div><div style={{fontSize:".5rem",color:T.brown3,whiteSpace:"nowrap",flexShrink:0}}>{d}</div></div>))}</div>);

