function Dashboard({goto,role}){
  const nav=NAVS[role];
  const info=INFO[role];
  const[view,setView]=useState("overview");
  const[open,setOpen]=useState(false);
  const w=useW(),isMobile=w<768;
  const cur=nav.find(i=>i.id===view);
  const SB=()=>(<>
    <div style={{padding:"1.4rem 1.5rem",borderBottom:`1px solid ${T.lineL}`}}><Logo/><div style={{fontSize:".42rem",letterSpacing:".2em",textTransform:"uppercase",color:T.brown3,marginTop:".5rem"}}>{info.label}</div></div>
    <div style={{padding:"1rem 1.5rem",borderBottom:`1px solid ${T.lineL}`,display:"flex",alignItems:"center",gap:".8rem"}}><div style={{width:34,height:34,background:T.brown,display:"flex",alignItems:"center",justifyContent:"center",fontFamily:"'Cormorant Garamond',serif",fontSize:".9rem",color:T.cream,flexShrink:0}}>{info.ini}</div><div><div style={{fontSize:".62rem",fontWeight:500,color:T.brown}}>{info.name}</div><div style={{fontSize:".46rem",letterSpacing:".12em",textTransform:"uppercase",color:T.gold,marginTop:".15rem"}}>{info.role}</div></div></div>
    <nav style={{flex:1,padding:".8rem 0",overflowY:"auto"}}>{nav.map((item,i)=>item.s?(<div key={i} style={{fontSize:".42rem",letterSpacing:".22em",textTransform:"uppercase",color:T.brown3,padding:".3rem 1.5rem",marginTop:".5rem",opacity:.7}}>{item.s}</div>):(<div key={item.id} onClick={()=>{setView(item.id);if(isMobile)setOpen(false);}} style={{display:"flex",alignItems:"center",gap:".7rem",padding:".65rem 1.5rem",fontSize:".6rem",cursor:"pointer",color:view===item.id?T.brown:T.brown3,background:view===item.id?T.goldL:"transparent",borderRight:view===item.id?`2px solid ${T.gold}`:"2px solid transparent"}}><span style={{color:view===item.id?T.gold:T.brown3,flexShrink:0,display:"flex"}}><item.ic/></span><span style={{flex:1}}>{item.lb}</span>{item.b&&<span style={{background:T.gold,color:T.ivory,fontSize:".42rem",padding:".12rem .45rem",fontWeight:600}}>{item.b}</span>}</div>))}</nav>
    <div style={{padding:"1.1rem 1.5rem",borderTop:`1px solid ${T.lineL}`}}><button onClick={()=>goto("landing")} style={{display:"flex",alignItems:"center",gap:".5rem",background:"transparent",border:"none",cursor:"pointer",fontSize:".52rem",color:T.brown3,fontFamily:"'Montserrat',sans-serif",letterSpacing:".12em"}}><I.Key/> Déconnexion</button></div>
  </>);
  return(<div style={{display:"flex",minHeight:"100vh",background:T.cream}}>
    {!isMobile&&<div style={{width:245,background:T.ivory,display:"flex",flexDirection:"column",position:"fixed",top:0,left:0,bottom:0,borderRight:`1px solid ${T.lineL}`,zIndex:100}}><SB/></div>}
    {isMobile&&open&&<div style={{position:"fixed",inset:0,zIndex:200}}><div onClick={()=>setOpen(false)} style={{position:"absolute",inset:0,background:"rgba(26,14,8,.4)"}}/><div style={{position:"absolute",left:0,top:0,bottom:0,width:260,background:T.ivory,display:"flex",flexDirection:"column",borderRight:`1px solid ${T.lineL}`}}><SB/></div></div>}
    <div style={{marginLeft:isMobile?0:245,flex:1,minWidth:0}}>
      <div style={{background:T.ivory,padding:"1rem 1.5rem",display:"flex",justifyContent:"space-between",alignItems:"center",borderBottom:`1px solid ${T.lineL}`,position:"sticky",top:0,zIndex:90}}>
        <div style={{display:"flex",alignItems:"center",gap:"1rem"}}>
          {isMobile&&<div onClick={()=>setOpen(true)} style={{width:30,height:30,border:`1px solid ${T.line}`,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",gap:4,cursor:"pointer",flexShrink:0}}><div style={{width:12,height:"0.5px",background:T.brown}}/><div style={{width:12,height:"0.5px",background:T.brown}}/><div style={{width:12,height:"0.5px",background:T.brown}}/></div>}
          <div style={{display:"flex",alignItems:"center",gap:".5rem"}}>{cur?.ic&&<span style={{color:T.gold,display:"flex"}}><cur.ic/></span>}<div style={{fontFamily:"'Cormorant Garamond',serif",fontSize:isMobile?"1rem":"1.15rem",fontWeight:400,color:T.brown}}>{cur?.lb||"K Properties"}</div></div>
        </div>
        <div style={{display:"flex",alignItems:"center",gap:".6rem"}}>
          <div onClick={()=>setView("notifications"||"alertes")} style={{width:30,height:30,border:`1px solid ${T.line}`,display:"flex",alignItems:"center",justifyContent:"center",cursor:"pointer",color:T.brown3,position:"relative"}}><I.Bell/><div style={{position:"absolute",top:4,right:4,width:5,height:5,background:T.gold,borderRadius:"50%"}}/></div>
          <div onClick={()=>setView("messagerie")} style={{width:30,height:30,border:`1px solid ${T.line}`,display:"flex",alignItems:"center",justifyContent:"center",cursor:"pointer",color:T.brown3,position:"relative"}}><I.Message/><div style={{position:"absolute",top:4,right:4,width:5,height:5,background:T.gold,borderRadius:"50%"}}/></div>
          {!isMobile&&<Btn sz="sm" onClick={()=>goto("landing")}>← Site</Btn>}
        </div>
      </div>
      <div style={{padding:isMobile?"1.2rem":"1.8rem 2rem"}}><DView role={role} view={view} setView={setView}/></div>
    </div>
  </div>);
}

